  code=code.replace("(f.indexed?'مفهرس':'غير مفهرس')", "noonIndexStatus(f)");
  code=code.replace("kind.onchange=function(){updatePartialOptionVisibility();saveSearchOptionsToStorage()};", "kind.onchange=function(){updatePartialOptionVisibility();saveSearchOptionsToStorage();if(window.refreshSearchScopeIndexState)window.refreshSearchScopeIndexState()};");
  if(!code.contains("noonSyncIndexTypes(kind,forms,function(f)"))code=code.replace(" function renderDetails(forms){"," function renderDetails(forms){"+"if(noonSyncIndexTypes(kind,forms,function(f){var code=codeOf(f);return code&&noonSearchConfigVisible(code)&&noonSearchFormVisible(code)&&noonFormAllowed('search_forms',code)&&noonFormAllowed('search_ranges',code)})){updatePartialOptionVisibility();saveSearchOptionsToStorage();}");
