  if(!code.contains("/* NOON_LIVE_INDEX_TYPES_V1 */"))code="/* NOON_LIVE_INDEX_TYPES_V1 */\nfunction noonLuceneIndexTypes(){return String((window.NT_CONFIG||{}).search_index_type||window.search_engin_type||'').toLowerCase()==='lucene';}\nfunction noonRefreshIndexTypeMenu(select){if(select._refreshSearchDisplay)select._refreshSearchDisplay();var parent=select.parentNode,items=parent&&parent.getElementsByClassName?parent.getElementsByClassName('custom-select-option'):[],i;for(i=0;i<items.length&&i<select.options.length;i++){items[i].className='custom-select-option'+(select.options[i].disabled?' disabled':'');if(items[i].setAttribute)items[i].setAttribute('aria-disabled',select.options[i].disabled?'true':'false');}}\nfunction noonSyncIndexTypes(select,forms,visible){\n if(!noonLuceneIndexTypes()||!select||!forms||typeof forms.length!=='number')return false;\n var enabled={},known=forms.length===0,i,j,f,k,kinds,code,cfg=window.NT_CONFIG||{},defaults=cfg.forum_defaults||{},override,allowed,option,first=-1,previous=select.value;\n for(i=0;i<forms.length;i++){\n  f=forms[i]||{};if(typeof f!=='object')continue;\n  if(f.index_kinds||typeof f.indexed==='boolean')known=true;\n  if(f.installed===false)continue;\n  code=String(f.formid||f.id||'').toLowerCase();override=(cfg.forum_overrides||{})[code]||{};\n  allowed=Object.prototype.hasOwnProperty.call(override,'show_in_search')?override.show_in_search!==false:defaults.show_in_search!==false;\n  if(!allowed||(visible&&!visible(f)))continue;\n  kinds=f.index_kinds;\n  if(kinds){for(k in kinds)if(Object.prototype.hasOwnProperty.call(kinds,k)&&kinds[k])enabled[k]=true;if(kinds.full_index)enabled.wildcard_index=true;}\n  else if(f.indexed){enabled.full_index=enabled.partial_index=enabled.root_index=enabled.wildcard_index=true;}\n }\n if(!known)return false;\n for(j=0;j<select.options.length;j++){option=select.options[j];option.disabled=!enabled[option.value];if(!option.disabled&&first<0)first=j;}\n select.disabled=first<0;\n if(first>=0&&(!select.options[select.selectedIndex]||select.options[select.selectedIndex].disabled))select.selectedIndex=first;\n noonRefreshIndexTypeMenu(select);\n return previous!==select.value;\n}\n"+code;
  code=code.replace("<input type=\"checkbox\" name=\"indexForm\" value=\"'+escScope(code)+'\" checked=\"checked\">","<input type=\"checkbox\" name=\"indexForm\" value=\"'+escScope(code)+'\" checked=\"checked\"'+(f.partially_indexed?' data-required-partial=\"1\" disabled=\"disabled\"':'')+'>");
