  if(!code.contains("if(input&&input.getAttribute('data-required-partial')==='1')input.checked=true;"))code=code.replace("if(input&&input.name==='indexForm')searchStorageSet(","if(input&&input.getAttribute('data-required-partial')==='1')input.checked=true;\n   if(input&&input.name==='indexForm')searchStorageSet(");
  if(installed)return applyRangeStatus(code);
  return applyRangeStatus("/* NOON_PARTIAL_INDEX_UI_V1 */\nfunction noonIndexCanSearch(form,type){var engine=String((window.NT_CONFIG||{}).search_index_type||window.search_engin_type||'').toLowerCase();if(engine!=='lucene'||!form.index_kinds)return !!form.indexed;return !!form.index_kinds[type||'full_index'];}\nfunction noonIndexStatus(form){var en=/^en\\b/i.test(String(window.NT_I18N?NT_I18N.lang():document.documentElement.lang||''));if(form.indexed)return en?'Indexed':'مفهرس';if(form.partially_indexed)return(en?'Partially indexed':'مفهرس جزئياً')+' ('+(+form.indexed_count||1)+'/3)';return en?'Not indexed':'غير مفهرس';}\n"+code);
