 private static final String RANGE_STATUS="/* NOON_RANGE_COMPLETENESS_V1 */\nfunction noonIndexTypeCount(form){\n form=form||{};var k=form.index_kinds,n;\n if(form.index_status==='partial'||form.partially_indexed){n=+form.indexed_count||1;return Math.max(1,Math.min(2,n));}\n if(form.index_status==='none')return 0;\n if(Object.prototype.hasOwnProperty.call(form,'indexed_count'))return Math.max(0,Math.min(3,+form.indexed_count||0));\n if(form.index_status==='full')return 3;\n if(k)return(k.full_index?1:0)+(k.partial_index?1:0)+(k.root_index?1:0);\n return form.indexed?3:0;\n}\nfunction noonIndexComplete(form){return noonIndexTypeCount(form)===3}\nfunction noonIndexAny(form){return noonIndexTypeCount(form)>0}\nfunction noonIndexStatus(form){\n var n=noonIndexTypeCount(form),en=/^en\\b/i.test(String(window.NT_I18N?NT_I18N.lang():document.documentElement.lang||''));\n if(n===3)return en?'Indexed':'مفهرس';\n if(n>0)return(en?'Partially indexed':'مفهرس جزئياً')+' ('+n+'/3)';\n return en?'Not indexed':'غير مفهرس';\n}\n";

